1	/**
2	 * 引擎公开错误类型。
3	 *
4	 * 设计约定：
5	 * - 提交阶段（普通交易 / 策略变更）对“内容不合法”的判定互不混用：
6	 *   普通交易 → InvalidTransaction；策略变更 → InvalidPolicyChange。
7	 * - RequestExpired 仅用于截止时间已过；PolicyConflict 仅用于执行时版本已漂移。
8	 * - NonceAlreadyUsedError 是既有重放防护的公开异常，策略变更沿用同一类型。
9	 */
10	
11	export class WalletError extends Error {
12	  constructor(message: string) {
13	    super(message);
14	    this.name = new.target.name;
15	  }
16	}
17	
18	/** 普通交易提交参数或签名不合法 */
19	export class InvalidTransaction extends WalletError {}
20	
21	/**
22	 * 原子批量普通交易提交不合法（不建任务、不消费 nonce、不改策略/队列）：
23	 * 列表为空或超过 64 项、收款地址非法或为零、金额越界、data 不是 Uint8Array、
24	 * 签名集合畸形、签名者非当前所有者、去重签名不足当前确认数。
25	 */
26	export class InvalidTransactionBatch extends WalletError {}
27	
28	/** 策略变更字段、版本、签名或 nonce 顺序不合法（不建任务、不消费 nonce、不改策略） */
29	export class InvalidPolicyChange extends WalletError {}
30	
31	/** 请求截止时间早于当前时间（提交时与执行时均可出现，不产生任务/不进入终态） */
32	export class RequestExpired extends WalletError {}
33	
34	/** 执行时发现任务绑定的策略版本已不是当前版本；任务进入既有失败终态 */
35	export class PolicyConflict extends WalletError {}
36	
37	/** nonce 已经被使用 —— 既有重放防护的公开异常，普通交易与策略变更共用 */
38	export class NonceAlreadyUsedError extends WalletError {
39	  readonly usedNonce: bigint;
40	  constructor(nonce: bigint) {
41	    super(`nonce already used: ${nonce}`);
42	    this.usedNonce = nonce;
43	  }
44	}
45	
46	/** 取消请求字段、nonce 顺序或签名不合法（不改变任务、不消费 nonce、不改策略） */
47	export class InvalidCancellation extends WalletError {}
48	
49	/** 目标任务已处于终态（executed / failed / cancelled），不可再取消 */
50	export class TaskCancellationConflict extends WalletError {}
51	
52	/** 对不存在任务、终态任务重复执行等队列层面的非法操作 */
53	export class TaskNotFoundError extends WalletError {}
54	
55	export class InvalidQueueStateError extends WalletError {}
56	
57	// ---------- 分阶段审批（普通交易 / 策略变更 / 批量交易共用同一组错误） ----------
58	
59	/** 审批 id 不存在（创建之外的加签 / 查询 / 提交均抛此异常） */
60	export class ApprovalNotFoundError extends WalletError {}
61	
62	/** 同一所有者对同一审批重复加签 */
63	export class DuplicateApprovalSignatureError extends WalletError {}
64	
65	/** 审批签名格式非法（非 65 字节）、与摘要不符或签名者不是当前所有者 */
66	export class InvalidApprovalSignatureError extends WalletError {}
67	
68	/** 审批截止时间已过（加签 / 提交时抛出；查询状态为 expired） */
69	export class ApprovalExpiredError extends WalletError {}
70	
71	/** 审批创建后策略版本已漂移（加签 / 提交时抛出；查询状态为 conflicted；过期优先于此） */
72	export class ApprovalPolicyConflictError extends WalletError {}
73	
74	/** 审批已完成提交（之后加签 / 重复提交抛出；查询状态为 submitted） */
75	export class ApprovalAlreadySubmittedError extends WalletError {}
76	
77	/** 提交时收集到的去重签名数不足审批创建时的确认数 */
78	export class ApprovalThresholdNotMetError extends WalletError {}
79	
80	/** 提交时审批绑定的 nonce 不等于当前 expectedNonce（尚未被消费但顺序不符） */
81	export class ApprovalNonceConflictError extends WalletError {}
82	
83	// ---------- 统一审批撤销（普通交易 / 策略变更 / 批量交易审批共用） ----------
84	
85	/**
86	 * 撤销请求本身不合法：approvalId 非字符串、nonce/deadline 无法安全转换或越界、
87	 * 签名集合畸形（非数组、空、元素非 65 字节、签名无法恢复）。
88	 * 校验顺序中最先发生（字段层），失败不消费 nonce、不改变任何状态。
89	 */
90	export class InvalidApprovalRevocationRequest extends WalletError {}
91	
92	/**
93	 * 撤销签名无效：签名与 safe-wallet/approval-revoke/v1 摘要不匹配（恢复出的签名者
94	 * 对不上任何当前所有者），或签名者不是当前所有者。跨钱包 / 跨审批 / 其他操作域的
95	 * 签名在此一并拒绝。
96	 */
97	export class InvalidApprovalRevocationSigner extends WalletError {}
98	
99	/** 撤销请求收集到的去重当前所有者签名数不足当前确认数 */
100	export class ApprovalRevocationThresholdNotMetError extends WalletError {}
101	
102	/** 撤销请求 nonce 未耗用但不等于当前 expectedNonce（顺序错；nonce 复用仍抛 NonceAlreadyUsedError） */
103	export class InvalidApprovalRevocationNonceError extends WalletError {}
104	
105	/**
106	 * 目标审批与撤销操作冲突：审批已撤销（重复撤销 / 再加签 / 再提交）或已提交
107	 * （对应任务已建立，撤销不适用；其未消费 nonce 的取消走既有 cancelTask）。
108	 */
109	export class ApprovalRevocationConflictError extends WalletError {}
110

