/**
 * 引擎公开错误类型。
 *
 * 设计约定：
 * - 提交阶段（普通交易 / 策略变更）对“内容不合法”的判定互不混用：
 *   普通交易 → InvalidTransaction；策略变更 → InvalidPolicyChange。
 * - RequestExpired 仅用于截止时间已过；PolicyConflict 仅用于执行时版本已漂移。
 * - NonceAlreadyUsedError 是既有重放防护的公开异常，策略变更沿用同一类型。
 */

export class WalletError extends Error {
  constructor(message: string) {
    super(message);
    this.name = new.target.name;
  }
}

/** 普通交易提交参数或签名不合法 */
export class InvalidTransaction extends WalletError {}

/**
 * 原子批量普通交易提交不合法（不建任务、不消费 nonce、不改策略/队列）：
 * 列表为空或超过 64 项、收款地址非法或为零、金额越界、data 不是 Uint8Array、
 * 签名集合畸形、签名者非当前所有者、去重签名不足当前确认数。
 */
export class InvalidTransactionBatch extends WalletError {}

/** 策略变更字段、版本、签名或 nonce 顺序不合法（不建任务、不消费 nonce、不改策略） */
export class InvalidPolicyChange extends WalletError {}

/** 请求截止时间早于当前时间（提交时与执行时均可出现，不产生任务/不进入终态） */
export class RequestExpired extends WalletError {}

/** 执行时发现任务绑定的策略版本已不是当前版本；任务进入既有失败终态 */
export class PolicyConflict extends WalletError {}

/** nonce 已经被使用 —— 既有重放防护的公开异常，普通交易与策略变更共用 */
export class NonceAlreadyUsedError extends WalletError {
  readonly usedNonce: bigint;
  constructor(nonce: bigint) {
    super(`nonce already used: ${nonce}`);
    this.usedNonce = nonce;
  }
}

/** 取消请求字段、nonce 顺序或签名不合法（不改变任务、不消费 nonce、不改策略） */
export class InvalidCancellation extends WalletError {}

/** 目标任务已处于终态（executed / failed / cancelled），不可再取消 */
export class TaskCancellationConflict extends WalletError {}

/** 对不存在任务、终态任务重复执行等队列层面的非法操作 */
export class TaskNotFoundError extends WalletError {}

export class InvalidQueueStateError extends WalletError {}

// ---------- 分阶段审批（普通交易 / 策略变更 / 批量交易共用同一组错误） ----------

/** 审批 id 不存在（创建之外的加签 / 查询 / 提交均抛此异常） */
export class ApprovalNotFoundError extends WalletError {}

/** 同一所有者对同一审批重复加签 */
export class DuplicateApprovalSignatureError extends WalletError {}

/** 审批签名格式非法（非 65 字节）、与摘要不符或签名者不是当前所有者 */
export class InvalidApprovalSignatureError extends WalletError {}

/** 审批截止时间已过（加签 / 提交时抛出；查询状态为 expired） */
export class ApprovalExpiredError extends WalletError {}

/** 审批创建后策略版本已漂移（加签 / 提交时抛出；查询状态为 conflicted；过期优先于此） */
export class ApprovalPolicyConflictError extends WalletError {}

/** 审批已完成提交（之后加签 / 重复提交抛出；查询状态为 submitted） */
export class ApprovalAlreadySubmittedError extends WalletError {}

/** 提交时收集到的去重签名数不足审批创建时的确认数 */
export class ApprovalThresholdNotMetError extends WalletError {}

/** 提交时审批绑定的 nonce 不等于当前 expectedNonce（尚未被消费但顺序不符） */
export class ApprovalNonceConflictError extends WalletError {}

// ---------- 统一审批撤销（普通交易 / 策略变更 / 批量交易审批共用） ----------

/**
 * 撤销请求本身不合法：approvalId 非字符串、nonce/deadline 无法安全转换或越界、
 * 签名集合畸形（非数组、空、元素非 65 字节、签名无法恢复）。
 * 校验顺序中最先发生（字段层），失败不消费 nonce、不改变任何状态。
 */
export class InvalidApprovalRevocationRequest extends WalletError {}

/**
 * 撤销签名无效：签名与 safe-wallet/approval-revoke/v1 摘要不匹配（恢复出的签名者
 * 对不上任何当前所有者），或签名者不是当前所有者。跨钱包 / 跨审批 / 其他操作域的
 * 签名在此一并拒绝。
 */
export class InvalidApprovalRevocationSigner extends WalletError {}

/** 撤销请求收集到的去重当前所有者签名数不足当前确认数 */
export class ApprovalRevocationThresholdNotMetError extends WalletError {}

/** 撤销请求 nonce 未耗用但不等于当前 expectedNonce（顺序错；nonce 复用仍抛 NonceAlreadyUsedError） */
export class InvalidApprovalRevocationNonceError extends WalletError {}

/**
 * 目标审批与撤销操作冲突：审批已撤销（重复撤销 / 再加签 / 再提交）或已提交
 * （对应任务已建立，撤销不适用；其未消费 nonce 的取消走既有 cancelTask）。
 */
export class ApprovalRevocationConflictError extends WalletError {}

content.content:
1	/**
2	 * 多签钱包策略引擎。
3	 *
4	 * 在阈值策略、签名收集、重放防护、FIFO 执行队列、策略变更任务与任务取消之上，新增
5	 * “原子批量普通交易”：当前所有者以阈值签名（safe-wallet/tx-batch/v1 域，绑定钱包标识、
6	 * nonce、截止时间与按顺序编码的全部调用）提交一个有序调用列表（1..64 项）。
7	 * 批量任务只入队一个队列任务、只消费一个 nonce；执行时整批成功产生一个 transfer-batch
8	 * 回执（不产生部分执行回执），失败则整批不生效。批量任务沿用同一 FIFO 队列、取消语义与
9	 * 终态幂等；单笔交易 / 策略变更 / 取消签名均不能授权批量交易。
10	 *
11	 * 在此之上新增“普通交易分阶段审批”：createTransactionApproval 登记交易（不消费 nonce、
12	 * 不建任务），addApprovalSignature 逐个收集当前所有者签名（safe-wallet/tx-approval/v1 域，
13	 * 绑定创建时策略版本与完整交易字段），达到创建时确认数后由 submitApprovedTransaction 按
14	 * 既有 safe-wallet/tx/v1 摘要入队并只消费创建时 nonce。审批与直接提交的签名摘要互不通用。
15	 *
16	 * 再新增“策略变更分阶段审批”：createPolicyApproval 登记一次目标策略变更（绑定版本、nonce、
17	 * deadline、新所有者顺序与新确认数，不消费 nonce、不建任务、不改策略），
18	 * addPolicyApprovalSignature 逐个收集当前所有者签名（safe-wallet/policy-change-approval/v1
19	 * 域），达到创建时确认数后由 submitApprovedPolicyChange 按既有 safe-wallet/policy-change/v1
20	 * 摘要入队一个 policy-change 任务并只消费创建时 nonce。同一 nonce 可登记多个候选审批，
21	 * 登记/加签均不改策略、不耗 nonce、不动队列；提交后执行时若版本已漂移，仍按既有
22	 * PolicyConflict 失败终态处理，不改策略。
23	 *
24	 * 再新增“批量交易分阶段审批”：createBatchApproval 登记一个有序调用列表（绑定版本、nonce、
25	 * deadline 与 1..64 项 calls，不消费 nonce、不建任务、不改策略），addBatchApprovalSignature
26	 * 逐个收集当前所有者签名（safe-wallet/tx-batch-approval/v1 域，绑定钱包标识、版本、nonce、
27	 * deadline 与按顺序编码的全部调用），达到创建时确认数后由 submitBatchApproval 按既有
28	 * safe-wallet/tx-batch/v1 摘要入队一个 transaction-batch 任务并只消费创建时 nonce。
29	 * 审批签名与批量直接提交签名互不通用；执行保持原子回执、FIFO、取消与终态幂等。
30	 *
31	 * 最后新增“统一审批撤销”：revokeApproval 以阈值签名（safe-wallet/approval-revoke/v1 域，
32	 * 绑定钱包标识、目标审批摘要、nonce、deadline）撤销三类审批中尚未提交的任一个（含已过期、
33	 * 已版本漂移的审批）。成功只消费一次 nonce、返回 revoked 快照：不建任务、不产回执，不改
34	 * owners/confirmations/policyVersion 与既有任务；审批已收集签名者保留但全部失效。
35	 * 已提交审批不适用撤销（对应任务的取消走既有 cancelTask）；撤销/提交/取消等签名域两两独立。
36	 */
37	
38	import {
39	  type Address,
40	  ZERO_ADDRESS,
41	  isZeroAddress,
42	  normalizeAddress,
43	  parseSignature,
44	  recoverAddress,
45	} from './crypto.ts';
46	import {
47	  hashCancellation,
48	  hashBatchApproval,
49	  hashPolicyChange,
50	  hashPolicyApproval,
51	  hashTransaction,
52	  hashTransactionApproval,
53	  hashTransactionBatch,
54	  hashApprovalRevocation,
55	  type ApprovalRevocationRequest,
56	  type PolicyApprovalRequest,
57	  type PolicyChangeRequest,
58	  type TransactionApprovalRequest,
59	  type TransactionBatchApprovalRequest,
60	  type TransactionBatchRequest,
61	  type TransactionRequest,
62	} from './encoding.ts';
63	import {
64	  ApprovalAlreadySubmittedError,
65	  ApprovalExpiredError,
66	  ApprovalNonceConflictError,
67	  ApprovalNotFoundError,
68	  ApprovalPolicyConflictError,
69	  ApprovalRevocationConflictError,
70	  ApprovalRevocationThresholdNotMetError,
71	  ApprovalThresholdNotMetError,
72	  DuplicateApprovalSignatureError,
73	  InvalidApprovalRevocationNonceError,
74	  InvalidApprovalRevocationRequest,
75	  InvalidApprovalRevocationSigner,
76	  InvalidApprovalSignatureError,
77	  InvalidCancellation,
78	  InvalidPolicyChange,
79	  InvalidTransaction,
80	  InvalidTransactionBatch,
81	  NonceAlreadyUsedError,
82	  RequestExpired,
83	  PolicyConflict,
84	  InvalidQueueStateError,
85	  TaskCancellationConflict,
86	  TaskNotFoundError,
87	} from './errors.ts';
88	import { ExecutionQueue, type QueueTask } from './queue.ts';
89	import { createHash } from 'node:crypto';
90	
91	// ---------- 任务载荷 ----------
92	
93	export type WalletTaskPayload =
94	  | {
95	      kind: 'transaction';
96	      deadline: bigint;
97	      to: Address;
98	      value: bigint;
99	      data: Uint8Array;
100	    }
101	  | {
102	      kind: 'transaction-batch';
103	      deadline: bigint;
104	      /** 有序调用；顺序即执行顺序，执行回执按同一顺序给出 */
105	      calls: BatchCall[];
106	    }
107	  | {
108	      kind: 'policy-change';
109	      deadline: bigint;
110	      /** 提交时绑定的策略版本；执行时必须仍等于当前版本 */
111	      version: bigint;
112	      newOwners: Address[];
113	      newConfirmations: bigint;
114	    };
115	
116	/** 批量任务内的单次调用（规范化后的收款地址、原金额、原始 data 副本） */
117	export interface BatchCall {
118	  to: Address;
119	  value: bigint;
120	  data: Uint8Array;
121	}
122	
123	export type WalletTask = QueueTask<WalletTaskPayload>;
124	
125	export interface PolicyState {
126	  owners: Address[];
127	  confirmations: bigint;
128	  version: bigint;
129	}
130	
131	export interface WalletOptions {
132	  id: string;
133	  owners: Address[];
134	  confirmations: bigint | number;
135	  /** 注入时钟，返回 Unix 秒；默认取系统时间 */
136	  now?: () => bigint;
137	}
138	
139	export interface TransactionSubmission {
140	  nonce: bigint | number;
141	  deadline: bigint | number;
142	  to: string;
143	  value: bigint | number;
144	  data?: Uint8Array;
145	}
146	
147	export interface PolicyChangeSubmission {
148	  version: bigint | number;
149	  nonce: bigint | number;
150	  deadline: bigint | number;
151	  newOwners: string[];
152	  newConfirmations: bigint | number;
153	}
154	
155	export interface CancellationSubmission {
156	  /** 目标任务 id（队列快照中的任务标识） */
157	  taskId: string;
158	  nonce: bigint | number;
159	  deadline: bigint | number;
160	}
161	
162	/** 批量提交中的单次调用（原始输入；地址在校验时规范化） */
163	export interface BatchCallSubmission {
164	  to: string;
165	  value: bigint | number;
166	  /** 必含的调用数据（允许零长度）；必须是 Uint8Array */
167	  data: Uint8Array;
168	}
169	
170	export interface BatchTransactionSubmission {
171	  nonce: bigint | number;
172	  deadline: bigint | number;
173	  /** 有序调用列表：非空且最多 MAX_BATCH_CALLS 项，顺序参与签名且不得改变 */
174	  calls: readonly BatchCallSubmission[];
175	}
176	
177	/** 统一审批撤销请求：approvalId 指向三类审批中的任一个；nonce 为本次撤销自身的 nonce */
178	export interface ApprovalRevocationSubmission {
179	  approvalId: string;
180	  nonce: bigint | number;
181	  deadline: bigint | number;
182	}
183	
184	/** 批量交易调用数量上限（含） */
185	export const MAX_BATCH_CALLS = 64;
186	
187	// ---------- 普通交易分阶段审批 ----------
188	
189	/**
190	 * 审批生命周期：collecting → ready → submitted；expired / conflicted 为查询派生状态；
191	 * revoked 为撤销终态（由 revokeApproval 写入，优先级最高，快照保留已收集签名者但全部失效）
192	 */
193	export type ApprovalStatus =
194	  | 'collecting'
195	  | 'ready'
196	  | 'expired'
197	  | 'conflicted'
198	  | 'submitted'
199	  | 'revoked';
200	
201	/** 审批的公开快照（创建 / 加签 / 查询时返回） */
202	export interface TransactionApproval {
203	  /** 审批标识（由创建序号与审批摘要派生，引擎内唯一） */
204	  id: string;
205	  /** 审批签名摘要（hex，safe-wallet/tx-approval/v1 域） */
206	  digest: string;
207	  /** 创建时绑定的策略版本 */
208	  version: bigint;
209	  /** 创建时绑定的确认数（阈值） */
210	  confirmations: bigint;
211	  /** 已收集签名者（按加签顺序，去重） */
212	  signers: Address[];
213	  status: ApprovalStatus;
214	}
215	
216	/** 审批的内部记录：完整交易字段 + 签名收集状态 */
217	interface ApprovalRecord {
218	  id: string;
219	  digest: Buffer;
220	  version: bigint;
221	  confirmations: bigint;
222	  nonce: bigint;
223	  deadline: bigint;
224	  to: Address;
225	  value: bigint;
226	  data: Buffer;
