333	/** 安全标量转换：非法输入（undefined / 字符串等）归一为指定的 Invalid* 错误 */
334	function toBigInt(value: unknown, Invalid: new (msg: string) => Error, field: string): bigint {
335	  if (typeof value === 'bigint') return value;
336	  if (typeof value === 'number' && Number.isSafeInteger(value)) return BigInt(value);
337	  if (typeof value === 'string' && /^\d+$/.test(value.trim())) return BigInt(value.trim());
338	  throw new Invalid(`field "${field}" must be a non-negative integer`);
339	}
