488	   * 截止时间：签名无法改绑其他任务、其他钱包或其他时间窗口。
489	   *
490	   * 校验顺序（任一失败都不改变任务、不消费 nonce、不改变策略）：
491	   *   1) 字段非法 → InvalidCancellation
492	   *   2) nonce 复用 → NonceAlreadyUsedError（旧请求重放恒得此异常，即使已过期）
493	   *   3) deadline 早于当前时间 → RequestExpired
494	   *   4) nonce 顺序（须等于 expectedNonce）→ InvalidCancellation
495	   *   5) 目标不存在 → TaskNotFoundError；目标已终态 → TaskCancellationConflict
496	   *   6) 阈值签名（当前所有者、去重后达到当前确认数）→ InvalidCancellation
497	   *
498	   * 成功时目标任务由 queued 进入 cancelled 终态并返回：保留原 payload/digest/nonce，
499	   * 记录取消时间与取消摘要；不执行目标效果，不改变 owners/确认数/策略版本，
500	   * 只消费本次 nonce 并推进 expectedNonce。取消不要求任务在队首，也不调整队列顺序。
501	   */
502	  cancelTask(
503	    taskId: string,
504	    nonce: bigint | number,
505	    deadline: bigint | number,
506	    signatures: readonly Uint8Array[],
507	  ): WalletTask;
508	  cancelTask(sub: CancellationSubmission, signatures: readonly Uint8Array[]): WalletTask;
509	  cancelTask(
510	    a: string | CancellationSubmission,
511	    b: readonly Uint8Array[] | bigint | number,
512	    c?: bigint | number,
513	    d?: readonly Uint8Array[],
514	  ): WalletTask {
515	    const sub: CancellationSubmission =
516	      typeof a === 'string' || a === undefined || a === null
517	        ? { taskId: a as string, nonce: b as bigint | number, deadline: c as bigint | number }
518	        : a;
519	    const signatures: readonly Uint8Array[] =
520	      (typeof a === 'string' || a === undefined || a === null ? d : (b as readonly Uint8Array[])) ??
521	      ([] as readonly Uint8Array[]);
522	
523	    // (1) 字段安全转换（畸形输入只抛 InvalidCancellation）
524	    const nonce = toBigInt(sub.nonce, InvalidCancellation, 'nonce');
525	    if (!isNonNegativeInteger(nonce)) {
526	      throw new InvalidCancellation('nonce must be a non-negative integer');
527	    }
528	    // (2) nonce 复用优先于过期判定
529	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
530	
531	    const deadline = toBigInt(sub.deadline, InvalidCancellation, 'deadline');
532	    if (!isNonNegativeInteger(deadline)) throw new InvalidCancellation('deadline out of range');
533	    // (3) 截止时间
534	    if (deadline < this.now()) {
535	      throw new RequestExpired(`request deadline ${deadline} already passed`);
536	    }
537	    // (4) nonce 顺序：取消与提交共用同一严格递增序列
538	    if (nonce !== this.nextNonce) {
539	      throw new InvalidCancellation(`expected nonce ${this.nextNonce}, got ${nonce}`);
540	    }
541	
542	    // (5) 目标任务状态
543	    const taskId = sub.taskId;
544	    if (typeof taskId !== 'string' || taskId.length === 0) {
545	      throw new InvalidCancellation('taskId must be a non-empty string');
546	    }
547	    const target = this.queue.getTask(taskId);
548	    if (target === null) throw new TaskNotFoundError(`task not found: ${taskId}`);
549	    if (target.status !== 'queued') {
550	      throw new TaskCancellationConflict(`task ${taskId} is already ${target.status}`);
551	    }
552	
553	    // (6) 阈值签名：摘要绑定钱包标识、目标任务 digest、nonce、deadline
554	    const digest = hashCancellation({
555	      walletId: this.id,
556	      taskDigest: target.digest,
557	      nonce,
558	      deadline,
559	    });
560	    this.verifyThresholdSignatures(digest, signatures, InvalidCancellation);
561	
562	    // 原子生效：目标任务进入 cancelled 终态 + 消费 nonce；策略与队列顺序不变
563	    const cancelled = this.queue.cancel(taskId, this.now(), digest.toString('hex'));
564	    this.usedNonces.add(nonce);
565	    this.nextNonce = nonce + 1n;
566	    return cancelled;
567	  }
