569	  // ---------- 普通交易分阶段审批（签名收集与提交分离；旧入口行为不变） ----------
570	
571	  /**
572	   * 创建一笔普通交易的分阶段审批：只校验并登记，不消费 nonce、不建任务、不改策略。
573	   *
574	   * 审批摘要用 safe-wallet/tx-approval/v1 域，绑定钱包标识、创建时策略版本与完整交易字段
575	   * （data 复制保存），与直接提交的 safe-wallet/tx/v1 摘要互不通用。
576	   *
577	   * 校验顺序与 submitTransaction 一致（失败不产生任何状态变化）：
578	   *   1) nonce 复用 → NonceAlreadyUsedError
579	   *   2) deadline 早于当前时间 → RequestExpired
580	   *   3) 字段非法或 nonce 跳号（须等于 expectedNonce）→ InvalidTransaction
581	   *
582	   * 成功时返回审批快照（标识、摘要、版本、确认数、空签名者列表、collecting 状态）。
583	   */
584	  createTransactionApproval(sub: TransactionSubmission): TransactionApproval {
585	    // (1) nonce 安全转换与复用判定（复用优先于过期，与既有提交一致）
586	    const nonce = toBigInt(sub.nonce, InvalidTransaction, 'nonce');
587	    if (!isNonNegativeInteger(nonce)) throw new InvalidTransaction('nonce must be a non-negative integer');
588	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
589	
590	    // (2) 截止时间
591	    const deadline = toBigInt(sub.deadline, InvalidTransaction, 'deadline');
592	    if (!isNonNegativeInteger(deadline)) throw new InvalidTransaction('deadline out of range');
593	    if (deadline < this.now()) {
594	      throw new RequestExpired(`request deadline ${deadline} already passed`);
595	    }
596	    // (3) nonce 顺序：创建只登记不消费，但仍须绑定当前期望 nonce（跳号即非法）
597	    if (nonce !== this.nextNonce) {
598	      throw new InvalidTransaction(`expected nonce ${this.nextNonce}, got ${nonce}`);
599	    }
600	
601	    // (4) 交易字段校验与规范化（与直接提交同一套规则）
602	    const to = normalizeAddress(sub.to);
603	    if (to === null || isZeroAddress(to)) throw new InvalidTransaction('invalid or zero recipient address');
604	    const value = toBigInt(sub.value, InvalidTransaction, 'value');
605	    if (!isNonNegativeInteger(value)) throw new InvalidTransaction('value out of range');
606	    const dataField = sub.data;
607	    if (dataField !== undefined && !(dataField instanceof Uint8Array) && !ArrayBuffer.isView(dataField)) {
608	      throw new InvalidTransaction('data must be a byte array');
609	    }
610	    // 复制一份，避免创建后调用方改动同一缓冲区影响审批内容/摘要
611	    const data = Buffer.from((dataField as Uint8Array | undefined) ?? new Uint8Array());
612	
613	    const req: TransactionApprovalRequest = {
614	      walletId: this.id,
615	      version: this.version,
616	      nonce,
617	      deadline,
618	      to,
619	      value,
620	      data,
621	    };
622	    const digest = hashTransactionApproval(req);
623	    const id = createHash('sha256')
624	      .update(`approval:${this.approvalSeq}:${digest.toString('hex')}`)
625	      .digest('hex')
626	      .slice(0, 16);
627	    this.approvalSeq += 1;
628	
629	    const record: ApprovalRecord = {
630	      id,
631	      digest,
632	      version: this.version,
633	      confirmations: this.confirmations,
634	      nonce,
635	      deadline,
636	      to,
637	      value,
638	      data,
639	      signers: [],
640	      signatures: new Map(),
641	      submitted: false,
642	      revoked: false,
643	    };
644	    this.approvals.set(id, record);
645	    return this.approvalSnapshot(record);
646	  }
