648	  /**
649	   * 给审批追加一个 65 字节签名（每次一个）。
650	   *
651	   * 校验顺序：
652	   *   1) 审批不存在 → ApprovalNotFoundError
653	   *   2) 已提交 → ApprovalAlreadySubmittedError
654	   *   3) 已过期 → ApprovalExpiredError（过期优先于版本冲突）
655	   *   4) 策略版本漂移 → ApprovalPolicyConflictError
656	   *   5) 签名格式 / 与摘要不符 / 签名者非当前所有者 → InvalidApprovalSignatureError
657	   *   6) 同一所有者重复加签 → DuplicateApprovalSignatureError
658	   *
659	   * 达到创建时确认数后状态变为 ready；任一失败都不改变审批内容。
660	   */
661	  addApprovalSignature(approvalId: string, signature: Uint8Array): TransactionApproval {
662	    const record = this.getApprovalRecord(approvalId);
663	    this.assertApprovalActive(record);
664	
665	    if (!(signature instanceof Uint8Array) || signature.length !== 65) {
666	      throw new InvalidApprovalSignatureError('signature must be a 65-byte r||s||v blob');
667	    }
668	    const signer = recoverAddress(record.digest, Uint8Array.from(signature));
669	    if (signer === null) {
670	      throw new InvalidApprovalSignatureError('malformed or non-canonical signature');
671	    }
672	    if (!this.ownerSet.has(signer)) {
673	      throw new InvalidApprovalSignatureError('signature does not match approval or signer is not an owner');
674	    }
675	    if (record.signatures.has(signer)) {
676	      throw new DuplicateApprovalSignatureError(`owner already signed: ${signer}`);
677	    }
678	    record.signers.push(signer);
679	    record.signatures.set(signer, Buffer.from(signature));
680	    return this.approvalSnapshot(record);
681	  }
