1115	   *   1) 字段非法（approvalId 非字符串、nonce/deadline 非合法非负整数）或签名集合畸形
1116	   *      （非数组 / 空 / 元素非 65 字节 / 签名无法解析恢复）→ InvalidApprovalRevocationRequest
1117	   *   2) nonce 复用 → NonceAlreadyUsedError（旧撤销重放恒得此异常，即使已过期）
1118	   *   3) deadline 早于当前时间 → RequestExpired
1119	   *   4) nonce ≠ expectedNonce → InvalidApprovalRevocationNonceError
1120	   *   5) 审批不存在 → ApprovalNotFoundError
1121	   *   6) 审批已撤销或已提交 → ApprovalRevocationConflictError
1122	   *      （revoked 优先；expired / conflicted 仍可撤销，不在此拦截）
1123	   *   7) 签名与摘要不匹配 / 签名者非当前所有者 → InvalidApprovalRevocationSigner；
1124	   *      去重签名者不足当前确认数 → ApprovalRevocationThresholdNotMetError
1125	   *
1126	   * 成功只消费一次本次撤销 nonce 并推进 expectedNonce，返回目标审批的 revoked 快照：
1127	   * 不建任务、不产执行回执，不改 owners / confirmations / policyVersion 与既有任务。
1128	   * 撤销后再加签、再撤销或提交都抛 ApprovalRevocationConflictError。
1129	   */
1130	  revokeApproval(
1131	    sub: ApprovalRevocationSubmission,
1132	    signatures: readonly Uint8Array[],
1133	  ): TransactionApproval | PolicyApproval | BatchApproval;
1134	  revokeApproval(
1135	    approvalId: string,
1136	    nonce: bigint | number,
1137	    deadline: bigint | number,
1138	    signatures: readonly Uint8Array[],
1139	  ): TransactionApproval | PolicyApproval | BatchApproval;
1140	  revokeApproval(
1141	    a: ApprovalRevocationSubmission | string,
1142	    b: readonly Uint8Array[] | bigint | number,
1143	    c?: bigint | number,
1144	    d?: readonly Uint8Array[],
1145	  ): TransactionApproval | PolicyApproval | BatchApproval {
1146	    const sub: ApprovalRevocationSubmission =
1147	      typeof a === 'string' || a === undefined || a === null
1148	        ? { approvalId: a as string, nonce: b as bigint | number, deadline: c as bigint | number }
1149	        : a;
1150	    const signatures: readonly Uint8Array[] =
1151	      (typeof a === 'string' || a === undefined || a === null
1152	        ? d
1153	        : (b as readonly Uint8Array[])) ?? ([] as readonly Uint8Array[]);
1154	
1155	    // (1) 字段层：approvalId 必须是非空字符串；签名集合必须先通过形状与可解析性检查
1156	    //     （畸形请求不允许落到 nonce / 审批查询阶段）
1157	    if (typeof sub.approvalId !== 'string' || sub.approvalId.length === 0) {
1158	      throw new InvalidApprovalRevocationRequest('approvalId must be a non-empty string');
1159	    }
1160	    if (!Array.isArray(signatures)) {
1161	      throw new InvalidApprovalRevocationRequest('signatures must be an array');
1162	    }
1163	    if (signatures.length === 0) {
1164	      throw new InvalidApprovalRevocationRequest('missing signatures');
1165	    }
1166	    const blobs: Uint8Array[] = [];
1167	    for (const sig of signatures) {
1168	      if (!(sig instanceof Uint8Array) || sig.length !== 65) {
1169	        throw new InvalidApprovalRevocationRequest(
1170	          'each signature must be a 65-byte r||s||v blob',
1171	        );
1172	      }
1173	      // 先做可解析性检查：无法恢复（含 high-s / 畸形曲线点）属于请求格式问题
1174	      if (parseSignature(sig) === null) {
1175	        throw new InvalidApprovalRevocationRequest('malformed or non-canonical signature');
1176	      }
1177	      blobs.push(Uint8Array.from(sig));
1178	    }
1179	
1180	    const nonce = toBigInt(sub.nonce, InvalidApprovalRevocationRequest, 'nonce');
1181	    if (!isNonNegativeInteger(nonce)) {
1182	      throw new InvalidApprovalRevocationRequest('nonce must be a non-negative integer');
1183	    }
1184	    // (2) nonce 复用优先于过期判定（与提交 / 取消同一口径）
1185	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
1186	
1187	    const deadline = toBigInt(sub.deadline, InvalidApprovalRevocationRequest, 'deadline');
1188	    if (!isNonNegativeInteger(deadline)) {
1189	      throw new InvalidApprovalRevocationRequest('deadline out of range');
1190	    }
1191	    // (3) 截止时间
1192	    if (deadline < this.now()) {
1193	      throw new RequestExpired(`request deadline ${deadline} already passed`);
1194	    }
1195	    // (4) nonce 顺序：撤销与提交 / 取消共用同一严格递增序列
1196	    if (nonce !== this.nextNonce) {
1197	      throw new InvalidApprovalRevocationNonceError(
1198	        `expected nonce ${this.nextNonce}, got ${nonce}`,
1199	      );
1200	    }
1201	
1202	    // (5) 审批存在性：三类审批命名空间统一按 id 查找
1203	    const located = this.locateApproval(sub.approvalId);
1204	    if (located === null) {
1205	      throw new ApprovalNotFoundError(`approval not found: ${sub.approvalId}`);
1206	    }
1207	
1208	    // (6) 审批状态：已撤销 / 已提交即冲突（revoked 优先）；expired / conflicted 仍可撤销
1209	    if (located.record.revoked) {
1210	      throw new ApprovalRevocationConflictError(
1211	        `approval ${located.record.id} already revoked`,
1212	      );
1213	    }
1214	    if (located.record.submitted) {
1215	      throw new ApprovalRevocationConflictError(
1216	        `approval ${located.record.id} already submitted`,
1217	      );
1218	    }
1219	
1220	    // (7) 阈值签名：摘要绑定钱包标识、目标审批摘要、nonce、deadline
1221	    const req: ApprovalRevocationRequest = {
1222	      walletId: this.id,
1223	      approvalDigest: located.record.digest.toString('hex'),
1224	      nonce,
1225	      deadline,
1226	    };
1227	    const digest = hashApprovalRevocation(req);
1228	    const signerSet = new Set<Address>();
1229	    for (const blob of blobs) {
1230	      // 形状与可解析性已在字段层校验；此处恢复签名者：对不上当前所有者即签名无效
1231	      const signer = recoverAddress(digest, blob);
1232	      if (signer === null || !this.ownerSet.has(signer)) {
1233	        throw new InvalidApprovalRevocationSigner(
1234	          'signature does not match revocation or signer is not a current owner',
1235	        );
1236	      }
1237	      signerSet.add(signer); // 地址去重：同一所有者多签只计一次
1238	    }
1239	    if (BigInt(signerSet.size) < this.confirmations) {
1240	      throw new ApprovalRevocationThresholdNotMetError(
1241	        `threshold not met: need ${this.confirmations} distinct current owners, got ${signerSet.size}`,
1242	      );
1243	    }
1244	
1245	    // 原子生效：审批进入 revoked 终态 + 只消费本次撤销 nonce；
1246	    // 不建任务、不产回执，策略与既有任务不变，原审批签名保留但失效
1247	    const revocation: RevocationRecord = {
1248	      revokedAt: this.now(),
1249	      digest,
1250	      signers: [...signerSet],
1251	      nonce,
1252	      deadline,
1253	    };
1254	    located.record.revoked = true;
1255	    located.record.revocation = revocation;
1256	    this.usedNonces.add(nonce);
1257	    this.nextNonce = nonce + 1n;
1258	    return this.approvalSnapshotOf(located);
1259	  }
