1275	  // ============================================================
1276	  // 内部实现
1277	  // ============================================================
1278	
1279	  /**
1280	   * 统一提交入口。raw 接收未经转换的原始标量（bigint/number/string），
1281	   * 所有转换与字段合法性判定都在这里完成，保证只能抛出约定错误类型。
1282	   */
1283	  private submit(
1284	    kind: WalletTaskPayload['kind'],
1285	    raw: Record<string, unknown>,
1286	    signatures: readonly Uint8Array[],
1287	  ): WalletTask {
1288	    const Invalid =
1289	      kind === 'policy-change'
1290	        ? InvalidPolicyChange
1291	        : kind === 'transaction-batch'
1292	          ? InvalidTransactionBatch
1293	          : InvalidTransaction;
1294	
1295	    // 校验优先级（任一失败都不建任务、不消费 nonce、不改策略）：
1296	    //   1) nonce 复用 → 既有重放防护的公开异常（旧请求重放即使已过期也仍报复用）
1297	    //   2) 截止时间早于当前时间 → RequestExpired
1298	    //   3) 字段 / 版本 / nonce 顺序 / 签名 → 对应 Invalid*
1299	    const nonce = toBigInt(raw.nonce, Invalid, 'nonce');
1300	    if (!isNonNegativeInteger(nonce)) throw new Invalid('nonce must be a non-negative integer');
1301	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
1302	
1303	    const deadline = toBigInt(raw.deadline, Invalid, 'deadline');
1304	    if (!isNonNegativeInteger(deadline)) throw new Invalid('deadline out of range');
1305	    if (deadline < this.now()) {
1306	      throw new RequestExpired(`request deadline ${deadline} already passed`);
1307	    }
1308	    if (nonce !== this.nextNonce) throw new Invalid(`expected nonce ${this.nextNonce}, got ${nonce}`);
1309	
1310	    // (3) 字段校验 + 规范化
1311	    let payload: WalletTaskPayload;
1312	    let digest: Buffer;
1313	    if (kind === 'transaction') {
1314	      const to = normalizeAddress(raw.to as string);
1315	      if (to === null || isZeroAddress(to)) throw new Invalid('invalid or zero recipient address');
1316	      const value = toBigInt(raw.value, Invalid, 'value');
1317	      if (!isNonNegativeInteger(value)) throw new Invalid('value out of range');
1318	      const dataField = raw.data;
1319	      if (
1320	        dataField !== undefined &&
1321	        !(dataField instanceof Uint8Array) &&
1322	        !ArrayBuffer.isView(dataField)
1323	      ) {
1324	        throw new Invalid('data must be a byte array');
1325	      }
1326	      const data = Buffer.from((dataField as Uint8Array | undefined) ?? new Uint8Array());
1327	      const req: TransactionRequest = {
1328	        walletId: this.id,
1329	        nonce,
1330	        deadline,
1331	        to,
1332	        value,
1333	        data,
1334	      };
1335	      digest = hashTransaction(req);
1336	      payload = { kind: 'transaction', deadline, to, value, data };
1337	    } else if (kind === 'transaction-batch') {
1338	      // 有序调用列表：1..64 项；逐项规范化收款地址、金额与 data（顺序保持不变）
1339	      const calls = this.normalizeBatchCalls(raw.calls);
1340	      const req: TransactionBatchRequest = {
1341	        walletId: this.id,
1342	        nonce,
1343	        deadline,
1344	        calls,
1345	      };
1346	      digest = hashTransactionBatch(req);
1347	      payload = { kind: 'transaction-batch', deadline, calls };
1348	    } else {
1349	      // (3) 版本与目标策略字段（直接提交与分阶段审批共用同一套规则）
1350	      const { version, newOwners, newConfirmations } = this.normalizePolicyChangeFields(raw);
1351	      const req: PolicyChangeRequest = {
1352	        walletId: this.id,
1353	        version,
1354	        nonce,
1355	        deadline,
1356	        newOwners,
1357	        newConfirmations,
1358	      };
1359	      digest = hashPolicyChange(req);
1360	      payload = { kind: 'policy-change', deadline, version, newOwners, newConfirmations };
1361	    }
1362	
1363	    // (4) 阈值签名：恢复 → 去重 → 必须为当前所有者 → 数量达到当前确认数
1364	    this.verifyThresholdSignatures(digest, signatures, Invalid);
1365	
1366	    // (5) 原子生效（到队列为止）：入队 + 消费 nonce。
1367	    //     入队失败（同一摘要重复等）时不消费 nonce。
1368	    let task: WalletTask;
1369	    try {
1370	      task = this.queue.enqueue({
1371	        nonce,
1372	        digest: digest.toString('hex'),
1373	        payload,
1374	        submittedAt: this.now(),
1375	      });
1376	    } catch (err) {
1377	      if (err instanceof InvalidQueueStateError) throw new Invalid(err.message);
1378	      throw err;
1379	    }
1380	    this.usedNonces.add(nonce);
1381	    this.nextNonce = nonce + 1n;
1382	    return task;
1383	  }
1384	
1385	  /**
1386	   * 规范化批量调用列表：必须是 1..MAX_BATCH_CALLS 项的数组，每项是对象，
1387	   * 收款地址合法且非零、金额为 256 位以内非负整数、data 必须是 Uint8Array。
1388	   * 保持输入顺序；任何畸形都归为 InvalidTransactionBatch。
1389	   */
1390	  private normalizeBatchCalls(rawCalls: unknown): BatchCall[] {
1391	    if (!Array.isArray(rawCalls) || rawCalls.length === 0) {
1392	      throw new InvalidTransactionBatch('calls must be a non-empty array');
1393	    }
1394	    if (rawCalls.length > MAX_BATCH_CALLS) {
1395	      throw new InvalidTransactionBatch(`too many calls: ${rawCalls.length} > ${MAX_BATCH_CALLS}`);
1396	    }
1397	    const calls: BatchCall[] = [];
1398	    for (const rawCall of rawCalls) {
1399	      if (typeof rawCall !== 'object' || rawCall === null) {
1400	        throw new InvalidTransactionBatch('each batch call must be an object');
1401	      }
1402	      const call = rawCall as Record<string, unknown>;
1403	      const to = normalizeAddress(call.to as string);
1404	      if (to === null || isZeroAddress(to)) {
1405	        throw new InvalidTransactionBatch('invalid or zero recipient address in batch call');
1406	      }
1407	      const value = toBigInt(call.value, InvalidTransactionBatch, 'value');
1408	      if (!isNonNegativeInteger(value)) {
1409	        throw new InvalidTransactionBatch('batch call value out of range');
1410	      }
1411	      if (!(call.data instanceof Uint8Array)) {
1412	        throw new InvalidTransactionBatch('batch call data must be a Uint8Array');
1413	      }
1414	      // 复制一份，避免入队后调用方再改动同一缓冲区影响任务内容/摘要
1415	      calls.push({ to, value, data: Buffer.from(call.data) });
1416	    }
1417	    return calls;
1418	  }
