1420	  /**
1421	   * 规范化策略变更字段（直接提交 proposePolicyChange 与分阶段审批 createPolicyApproval 共用）：
1422	   *   - 版本必须绑定当前版本（提交/创建时不匹配 → InvalidPolicyChange；执行时漂移 → PolicyConflict）
1423	   *   - 新所有者列表非空、无重复、无零地址、全部合法（保持输入顺序）
1424	   *   - 新确认数大于 0 且不超过新所有者数量
1425	   * 任一不合法都抛 InvalidPolicyChange；成功返回规范化后的值。
1426	   */
1427	  private normalizePolicyChangeFields(raw: Record<string, unknown>): {
1428	    version: bigint;
1429	    newOwners: Address[];
1430	    newConfirmations: bigint;
1431	  } {
1432	    const version = toBigInt(raw.version, InvalidPolicyChange, 'version');
1433	    if (version !== this.version) {
1434	      throw new InvalidPolicyChange(
1435	        `policy version mismatch: bound ${version}, current ${this.version}`,
1436	      );
1437	    }
1438	    const newOwners = normalizeOwnerList(raw.newOwners as string[], InvalidPolicyChange);
1439	    const newConfirmations = toBigInt(raw.newConfirmations, InvalidPolicyChange, 'newConfirmations');
1440	    if (newConfirmations <= 0n || newConfirmations > BigInt(newOwners.length)) {
1441	      throw new InvalidPolicyChange(
1442	        `new confirmations must be within 1..new owners (${newOwners.length}), got ${newConfirmations}`,
1443	      );
1444	    }
1445	    return { version, newOwners, newConfirmations };
1446	  }
