1450	  /** 三类审批统一定位结果（撤销入口跨命名空间按 id 查找） */
1451	  private locateApproval(
1452	    approvalId: string,
1453	  ):
1454	    | { kind: 'transaction'; record: ApprovalRecord }
1455	    | { kind: 'policy'; record: PolicyApprovalRecord }
1456	    | { kind: 'batch'; record: BatchApprovalRecord }
1457	    | null {
