1485	  /**
1486	   * 已撤销 / 已提交 / 已过期 / 版本漂移的审批不可再加签或提交。
1487	   * revoked 优先级最高（撤销后加签 / 提交统一抛 ApprovalRevocationConflictError），
1488	   * 其次 submitted（ApprovalAlreadySubmittedError），过期优先于版本冲突。
1489	   */
1490	  private assertApprovalActive(record: ApprovalRecord): void {
1491	    if (record.revoked) {
1492	      throw new ApprovalRevocationConflictError(`approval ${record.id} already revoked`);
1493	    }
1494	    if (record.submitted) throw new ApprovalAlreadySubmittedError(`approval ${record.id} already submitted`);
1495	    if (record.deadline < this.now()) {
1496	      throw new ApprovalExpiredError(`approval deadline ${record.deadline} already passed`);
1497	    }
1498	    if (record.version !== this.version) {
1499	      throw new ApprovalPolicyConflictError(
1500	        `policy version drifted: approval bound ${record.version}, current ${this.version}`,
1501	      );
1502	    }
1503	  }
