1505	  /** 派生状态：revoked > submitted > expired > conflicted > ready > collecting */
1506	  private approvalStatus(record: ApprovalRecord): ApprovalStatus {
1507	    if (record.revoked) return 'revoked';
1508	    if (record.submitted) return 'submitted';
1509	    if (record.deadline < this.now()) return 'expired';
1510	    if (record.version !== this.version) return 'conflicted';
1511	    return BigInt(record.signers.length) >= record.confirmations ? 'ready' : 'collecting';
1512	  }
