1563	  private policyApprovalSnapshot(record: PolicyApprovalRecord): PolicyApproval {
1564	    return {
1565	      id: record.id,
1566	      digest: record.digest.toString('hex'),
1567	      version: record.version,
1568	      confirmations: record.confirmations,
1569	      nonce: record.nonce,
1570	      deadline: record.deadline,
1571	      newOwners: [...record.newOwners],
1572	      newConfirmations: record.newConfirmations,
1573	      signers: [...record.signers],
1574	      status: this.policyApprovalStatus(record),
1575	    };
1576	  }
1577	
1578	  // ---------- 批量交易分阶段审批内部辅助 ----------
1579	
1580	  private getBatchApprovalRecord(approvalId: string): BatchApprovalRecord {
1581	    const record =
1582	      typeof approvalId === 'string' ? this.batchApprovals.get(approvalId) : undefined;
1583	    if (record === undefined) {
1584	      throw new ApprovalNotFoundError(`batch approval not found: ${String(approvalId)}`);
1585	    }
1586	    return record;
1587	  }
1588	
1589	  /** 已撤销 / 已提交 / 已过期 / 版本漂移的批量审批不可再加签或提交（revoked 优先，过期优先于版本冲突） */
1590	  private assertBatchApprovalActive(record: BatchApprovalRecord): void {
1591	    if (record.revoked) {
1592	      throw new ApprovalRevocationConflictError(`batch approval ${record.id} already revoked`);
1593	    }
1594	    if (record.submitted) {
1595	      throw new ApprovalAlreadySubmittedError(`batch approval ${record.id} already submitted`);
1596	    }
1597	    if (record.deadline < this.now()) {
1598	      throw new ApprovalExpiredError(`batch approval deadline ${record.deadline} already passed`);
1599	    }
1600	    if (record.version !== this.version) {
1601	      throw new ApprovalPolicyConflictError(
1602	        `policy version drifted: approval bound ${record.version}, current ${this.version}`,
1603	      );
1604	    }
1605	  }
1606	
1607	  /** 派生状态：revoked > submitted > expired > conflicted > ready > collecting（与其他审批同一序） */
1608	  private batchApprovalStatus(record: BatchApprovalRecord): ApprovalStatus {
1609	    if (record.revoked) return 'revoked';
1610	    if (record.submitted) return 'submitted';
1611	    if (record.deadline < this.now()) return 'expired';
1612	    if (record.version !== this.version) return 'conflicted';
1613	    return BigInt(record.signers.length) >= record.confirmations ? 'ready' : 'collecting';
1614	  }
1615	
1616	  private batchApprovalSnapshot(record: BatchApprovalRecord): BatchApproval {
1617	    return {
1618	      id: record.id,
1619	      digest: record.digest.toString('hex'),
1620	      version: record.version,
1621	      confirmations: record.confirmations,
1622	      nonce: record.nonce,
1623	      deadline: record.deadline,
1624	      calls: record.calls.map((call) => ({ to: call.to, value: call.value, data: Buffer.from(call.data) })),
1625	      signers: [...record.signers],
1626	      status: this.batchApprovalStatus(record),
1627	    };
1628	  }
1629	
1630	  /** 按“当前策略”的所有者集合与确认数校验签名收集 */
1631	  private verifyThresholdSignatures(
1632	    digest: Uint8Array,
1633	    signatures: readonly Uint8Array[],
1634	    Invalid: new (msg: string) => Error,
1635	  ): void {
1636	    if (!Array.isArray(signatures)) {
1637	      throw new Invalid('signatures must be an array');
1638	    }
1639	    if (signatures.length === 0) throw new Invalid('missing signatures');
1640	
1641	    const signedBy = new Set<Address>();
1642	    for (const sig of signatures) {
1643	      if (!(sig instanceof Uint8Array) || sig.length !== 65) {
1644	        throw new Invalid('each signature must be a 65-byte r||s||v blob');
1645	      }
1646	      const signer = recoverAddress(digest, Uint8Array.from(sig));
1647	      if (signer === null) throw new Invalid('malformed or non-canonical signature');
1648	      if (!this.ownerSet.has(signer)) {
1649	        // 非所有者签名：既可能是伪造，也可能是签名载荷与提交内容不匹配
1650	        throw new Invalid('signature does not match payload or signer is not an owner');
1651	      }
1652	      signedBy.add(signer); // 地址去重：同一所有者多签只计一次
1653	    }
1654	    if (BigInt(signedBy.size) < this.confirmations) {
1655	      throw new Invalid(
1656	        `threshold not met: need ${this.confirmations} distinct owners, got ${signedBy.size}`,
1657	      );
1658	    }
1659	  }
1660	
1661	  /** 队列执行器回调：定义各类任务的生效语义 */
1662	  private applyTask(task: WalletTask): unknown {
1663	    const p = task.payload;
1664	    if (p.kind === 'transaction') {
1665	      // 普通交易既有执行结果：一个可观察的执行产物；不触碰策略状态。
1666	      // 截止时间只在提交阶段核对（RequestExpired），不作为执行闸门，以保持既有执行结果不变。
1667	      return {
1668	        kind: 'transfer',
1669	        to: p.to,
1670	        value: p.value,
1671	        data: Buffer.from(p.data).toString('hex'),
1672	      };
1673	    }
1674	
1675	    if (p.kind === 'transaction-batch') {
1676	      // 原子批量：执行器一次性产出整批回执。调用方（队列）在本回调正常返回后才写入
1677	      // executed 终态；本回调抛出则整批进入 failed，不产生部分执行回执。
1678	      // 截止时间同样不是执行闸门，与单笔普通交易保持一致。
1679	      return {
1680	        kind: 'transfer-batch',
1681	        calls: p.calls.map((call) => ({
1682	          to: call.to,
1683	          value: call.value,
1684	          data: Buffer.from(call.data).toString('hex'),
1685	        })),
1686	      };
1687	    }
1688	
1689	    // 策略变更：仅当绑定版本仍等于当前版本时生效
1690	    if (p.version !== this.version) {
1691	      throw new PolicyConflict(
1692	        `policy version drifted: task bound ${p.version}, current ${this.version}`,
1693	      );
1694	    }
1695	    // 所有者集合与确认数同时替换；版本恰好递增一次
1696	    this.owners = [...p.newOwners];
1697	    this.ownerSet.clear();
1698	    for (const o of this.owners) this.ownerSet.add(o);
1699	    this.confirmations = p.newConfirmations;
1700	    this.version += 1n;
1701	    return {
1702	      kind: 'policy-applied',
1703	      version: this.version,
1704	      owners: [...this.owners],
1705	      confirmations: this.confirmations,
1706	    };
1707	  }
1708	}
1709	
1710	// ---------- 所有者列表规范化（空/重复/零地址校验） ----------
1711	
1712	function normalizeOwnerList(
1713	  input: readonly string[],
1714	  ErrorCtor: typeof InvalidPolicyChange | typeof InvalidTransaction = InvalidPolicyChange,
1715	): Address[] {
1716	  if (!Array.isArray(input) || input.length === 0) {
1717	    throw new ErrorCtor('owners list must be a non-empty array');
1718	  }
1719	  const out: Address[] = [];
1720	  const seen = new Set<Address>();
1721	  for (const raw of input) {
1722	    const addr = normalizeAddress(raw);
1723	    if (addr === null) throw new ErrorCtor(`invalid owner address: ${String(raw)}`);
1724	    if (addr === ZERO_ADDRESS || isZeroAddress(addr)) {
1725	      throw new ErrorCtor('zero address is not allowed as owner');
1726	    }
1727	    if (seen.has(addr)) throw new ErrorCtor(`duplicate owner: ${addr}`);
1728	    seen.add(addr);
1729	    out.push(addr);
1730	  }
1731	  return out;
1732	}
1733

